import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        String s = new Scanner(System.in).next().toLowerCase();
        int answer = 0;
        for (int i = 1; i < s.length(); i++) if (s.charAt(i) != s.charAt(i - 1)) answer++;
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	var s string
	fmt.Scan(&s)
	s = strings.ToLower(s)
	answer := 0
	for i := 1; i < len(s); i++ {
		if s[i] != s[i-1] {
			answer++
		}
	}
	fmt.Println(answer)
}
